            refX="9"
            refY="5"
            markerWidth="7"
            markerHeight="7"
            orient="auto"
          >
            <path d="M0 0L10 5L0 10z" class="pmdf__head pmdf__head--muted" />
          </marker>
          <marker
            :id="`${uid}-arrow-no`"
            viewBox="0 0 10 10"
            refX="9"
            refY="5"
            markerWidth="7"
            markerHeight="7"
            orient="auto"
          >
            <path d="M0 0L10 5L0 10z" class="pmdf__head pmdf__head--no" />
          </marker>
          <marker
            :id="`${uid}-arrow-yes`"
