          class="pmdf__rail"
          :marker-end="`url(#${uid}-arrow-yes)`"
          fill="none"
        />

        <!-- Five stage bands -->
        <g
          v-for="band in layout.bands"
          :key="band.key"
          :class="[
            'pmdf__band',
            `pmdf__band--${band.no}`,
